const GI_ITEM_NAMES = new Map(GI_ITEM_LIST.map((item) => [item.id, item.name]))

/**
 * Get the display name for an item ID.
 * Falls back to a formatted version of the ID if not found.
 */
export function getItemName(itemId: string): string {
  const giName = GI_ITEM_NAMES.get(itemId)
  if (giName) {
    return giName
  }
  if (ITEM_NAMES[itemId]) {
    return ITEM_NAMES[itemId]
  }
  // Fallback: format the ID as a readable name
  let name = itemId.replace(/^(OOT_|MM_|SHARED_|EVENT_OOT_|EVENT_MM_|EVENT_)/, '')
  return name.split('_').map(word => 
    word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()
  ).join(' ')
}
